import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import { Image } from '../..';

const IMAGE_URL = 'https://www.robin-noorda.com/uploads/1/6/8/3/16830688/3347022_orig.jpg';
const BEES_LOGO_URL = 'https://media.gazetadopovo.com.br/2022/02/18112552/LOGO_BEES.png';

describe('Image', () => {
  it('should render image component without errors', () => {
    render(<Image src={IMAGE_URL} width="250px" />);

    expect(screen.getByRole('img')).toBeInTheDocument();
  });

  it('should render fit variant without errors', () => {
    render(<Image variant="fit" src={IMAGE_URL} width="250px" />);

    expect(screen.getByRole('img').getAttribute('class')).toMatch(/fit/gi);
  });

  it('should render stretch variant without errors', () => {
    render(<Image variant="stretch" src={IMAGE_URL} width="250px" />);

    expect(screen.getByRole('img').getAttribute('class')).toMatch(/stretch/gi);
  });

  it('should render overlay image without errors', () => {
    render(<Image isInteractive src={IMAGE_URL} width="250px" />);

    expect(screen.getByRole('img')).toBeInTheDocument();
  });

  it('should render error image when src is wrong', () => {
    render(<Image variant="stretch" src="not_found" width="250px" />);

    expect(screen.getByRole('img').getAttribute('src')).toBe('not_found');
  });

  it('should render custom error image', () => {
    render(
      <Image
        src="not_found"
        width="250px"
        customErrorImage={{
          src: { BEES_LOGO_URL },
          alt: 'Custom Image',
        }}
      />
    );

    const imageElement = screen.getByRole('img');

    fireEvent.error(imageElement, {
      target: imageElement,
    });

    expect(screen.getByAltText('Custom Image')).toBeInTheDocument();
  });

  it('should render call console.warn when custom error image is wrong', () => {
    render(
      <Image
        src="not_found"
        width="250px"
        customErrorImage={{
          src: 'custom_error_not_found',
          alt: 'Custom Image',
        }}
      />
    );
    jest.spyOn(console, 'warn').mockImplementation();

    const imageElement = screen.getByRole('img');

    fireEvent.error(imageElement, {
      target: imageElement,
    });

    const customImageElement = screen.getByAltText('Custom Image');

    fireEvent.error(customImageElement, {
      target: customImageElement,
    });

    expect(console.warn).toHaveBeenCalledWith(
      expect.stringContaining(
        "The custom image provided wasn't able to load, the default image will be used instead."
      )
    );
  });
});
